%[text] # Demo 4 Neo: Automatic ILC Velocity Sweep Experiment
%[text] Run this live script from any directory. Trajectory generation requires Symbolic Math Toolbox.
%[text] The build section only prepares the target. The velocity loop operates the real stage and must be run by the experiment operator.
%[text] ## 1. Load settings and design the feedback controller
clear; close all;
projectRoot = fileparts(fileparts(mfilename("fullpath")));
run(fullfile(projectRoot, "config", "config_tunable.m"));
figToolsRoot = fullfile(fileparts(projectRoot), "FigTools");
addpath(figToolsRoot, fullfile(figToolsRoot, "src"));

load(fullfile(projectRoot, "config", "data", "pana_params.mat"));
[plant, plantPath] = load_experiment_plant( ...
    projectRoot, plantDataFile, Ts);
Pd = plant.Pd;
Jn = plant.Jn;
Dn = plant.Dn;
Ndelay = plant.Ndelay;
fprintf("Sample rate: %.0f Hz, plant: %s\n", 1/Ts, plantPath); %[output:1cb9fd96]

Pd0 = struct( ...
    "m", Jn, ...
    "d", Dn, ...
    "k", 0, ...
    "delay", Ndelay, ...
    "lp", [0, 0, 0]); % Current plant data uses the Demo 3 model without the legacy tau filter.
[~, Gn0] = modelCreate(Pd0, Ts, Pd.Frequency);
Pdn = Gn0.modelDelayed;

[fb, ~, ~] = fbDesign(Pd, Ts);
Kd = fb.K;
%%
%[text] ## Check stability and sensitivity before operating the stage
figure; %[output:05e74868]
bopModel = bop;
bopModel.Title.String = "";
bode(Pdn, Pd, bopModel); %[output:05e74868]
legend("Model", "Measured", "Location", "northwest"); %[output:05e74868]
grid on; %[output:05e74868]
% pubfig(gcf);
%%
Smax = 2;
theta = linspace(0, 2*pi, 1000);

figure;
nyquistplot(Pdn*Kd, nop); hold on;
nyquistplot(Pd*Kd, nop);
plot(cos(theta)/Smax-1, sin(theta)/Smax, "k--"); hold off;
legend("Nominal", "Measured", "1/Smax boundary");
title("");
% pubfig(gcf);

figure; %[output:3d4e1a95]
S = feedback(1, Pd*Kd);
SmaxFrd = frd(Smax*ones(numel(Pd.Frequency), 1), ...
    Pd.Frequency, "FrequencyUnit", "Hz");
bopSensitivity = bop;
bopSensitivity.XLim = {[1, 1e3]};
bodemag(S, bopSensitivity); hold on; %[output:3d4e1a95]
bodemag(SmaxFrd, bopSensitivity, "k--"); hold off; %[output:3d4e1a95]
legend("Measured", "Smax"); %[output:3d4e1a95]
title(""); %[output:3d4e1a95]
% pubfig(gcf);
%%
%[text] ## 2. Design the learning and robustness filters
%[text] The nominal closed-loop inverse is implemented as $C+G\_n^{-1}$. The 420 Hz Q filter and the iteration-dependent learning gain reproduce the effective settings of the original experiment.
Ntrial = 15;
Fc = 420;             % Q-filter cutoff [Hz]
[Qz, Qp, Qgain] = butter(4, Fc/(1/(2*Ts)));
[Qsos, Qscale] = zp2sos(Qz, Qp, Qgain);
Q = zpk(Qz, Qp, Qgain, Ts);
Linv = feedback(Pdn, Kd);
J = feedback(Pd, Kd);

figure;
bodemag(Q^2*(1-J/Linv), bop); hold on;
bodemag(1-J/Linv, bop);
bodemag(Q^2, bop);
plot([1, 1/(2*Ts)], [0, 0], "k--"); hold off;
ylim([-150, 5]);
legend("Q^2(1-JL)", "1-JL", "Q^2", "Convergence boundary", ...
    "Location", "southwest");
title("ILC convergence condition");
% pubfig(gcf);
%%
%[text] ## 3. Define the velocity sweep and reference trajectory settings
dist = 1.25;                  % Travel distance [m]
v_max_list = 0.1:0.1:2.0;    % Constant-velocity settings [m/s]
a_max = 19.0;                 % Maximum acceleration [m/s^2]
t_pause = 1.0;                % Dwell at the turn-around point [s]
t_pre = 1.5;                  % Idle time before motion [s]
t_post = 1.5;                 % Idle time after motion [s]
feedbackFlag = 1;
%%
%[text] ## 4. Build the tunable model
%[text] Run this section after every sampleRateHz change. Demo 4 shares the target with Demo 3. Publish/install the generated module, set the TwinCAT task to Ts, and activate the configuration before the trials.
run(fullfile(projectRoot, "exp03_FF", "setup_tunable.m")); %[output:945d8957]
%%
%[text] ## 5. Run the automatic ILC velocity sweep
%[text] **Operator action:** this section connects to external mode once, then runs 10 ILC trials at each speed from 0.1 m/s through 1.5 m/s. Each speed uses a fresh ILC history and is saved separately. The sweep stops if a speed does not complete all 10 trials.
open(fullfile(projectRoot, ModelName));
confirmEachTrial = false;
velocitySweepEnabled = true;
ilcRunDir = create_run_directory(fullfile(projectRoot, "data", "ilc"), ...
    "velocity_sweep");
run(fullfile(projectRoot, "exp04_ILC", "obtainMeasurement.m")); %[output:985a57b3]
sweepResultFile = save_experiment_result(ilcRunDir, "ilc_velocity_sweep", ...
    struct("resultFiles", resultFiles, ...
    "completedTrialsByVelocity", completedTrialsByVelocity, ...
    "completedVelocities", completedVelocities, "v_max_list", v_max_list));

fprintf("Completed %d/%d velocity setting(s).\n", ...
    completedVelocities, numel(v_max_list));
%%
%[text] ## 6. Inspect the latest learned result
iteration = completedTrials; %[output:75497d2e]
resultFigures(1) = figure;
tiledlayout(3, 1);
nexttile; plot(t, history.r(:, iteration), t, history.y(:, iteration));
grid on; ylabel("Position [m]"); legend(["Reference", "Position"]);
title(sprintf("v_{max} = %.1f m/s, trial %d", v_max, iteration));
nexttile; plot(t, history.e(:, iteration));
grid on; ylabel("Tracking error [m]");
nexttile; plot(t, history.f(:, iteration), ...
    t, history.u(:, iteration)-history.f(:, iteration));
grid on; xlabel("Time [s]"); ylabel("Input [A]"); legend("FF", "FB");
linkaxes(findall(gcf, "Type", "axes"), "x");
% % pubfig(gcf);

resultFigures(2) = figure;
semilogy(0:completedTrials-1, history.eNorm(1:completedTrials), "-o");
grid on; xlabel("Iteration");
ylabel("||e||_2"); title("ILC learning curve");
% % pubfig(gcf);
figureFiles = save_experiment_figures(ilcRunDir, resultFigures);
fprintf("Sweep result: %s\n", sweepResultFile);

